- */
 #define I2C_TIMEOUT 50000U

 static int i2c_wait(uint32_t mask) {
     for (uint32_t t = 0; t < I2C_TIMEOUT; t++) {
         uint32_t isr = I2C1_ISR;
         if (isr & (I2C_ISR_NACKF | I2C_ISR_BERR | I2C_ISR_ARLO)) {
